// App is the main model, with a multi-view router
type App struct {
	config         *config.Config
	currentContext string
	// previousContext is the context left by the last switch, "" before any.
	previousContext string
	// ctxArgs is the snapshot behind the :ctx argument suggestions.
	ctxArgs  *contextArgs
	viewport viewport.Model
	// colorProfile is the terminal's colour profile as last reported by
	// Bubble Tea (tea.ColorProfileMsg). The zero value (Unknown) keeps the
	// terminal background untouched until the first report.
	colorProfile colorprofile.Profile

	// Navigation
	currentView command.ViewType
	views       map[command.ViewType]Screen
	sharedState *shared.State

	// terminalBlurred is set by tea.BlurMsg. The zero value means focused, so a
	// terminal without focus reporting behaves as before (DEVDESK-210).
	terminalBlurred bool

	// runWhenUnfocused is app.when_unfocused = run: a blur is still tracked but
	// suspends nothing. Fed at startup, on a context switch and on every save.
	if _, ok := a.views[command.ViewGitAuth]; ok {
		a.setView(command.ViewGitAuth, a.newAuthView())
	}
}

// newWithSize builds the router at a given size. New() reads that size from the
// terminal; splitting it out keeps the constructor itself free of I/O.
func newWithSize(cfg *config.Config, width, height int) *App {
	currentContext, _ := config.GetCurrentContext()

	// A store is always present: views never have to test for nil.
	// New() replaces this one with the real backend via useSecrets.
	sharedState := &shared.State{
		Secrets: credentials.SessionOnly("no secret store has been resolved yet"),
		// Created here and never replaced: the forwards outlive every view
		// rebuild, and a context switch with them (§3.1).
		Forwards: forward.New(),
	}
	// Telling the registry which port is not I/O — nothing is serving yet, so
	// nothing is bound — and a route opened before the first Cmd needs to know.
	_ = sharedState.Forwards.SetProxyPort(cfg.Network.ProxyPort)

	app := &App{
		config:           cfg,
		currentContext:   currentContext,
		viewport:         newViewport(width, height),
		currentView:      defaultView(cfg),
		views:            make(map[command.ViewType]Screen),
		sharedState:      sharedState,
		jobs:             jobs.New(),
		anim:             animationState{blinkOn: true},
		motionStatic:     cfg.App.StaticMotion(),
		runWhenUnfocused: cfg.App.RunsWhenUnfocused(),
		commandInput:     newCommandInput(),
		suggester:        command.NewSuggester(),
		sugCursor:        -1,
		width:            width,
		height:           height,
	}
	app.ctxArgs = &contextArgs{}
	app.suggester.WithProvider("context", app.ctxArgs)
	app.wantedProxyPort.Store(int64(cfg.Network.ProxyPort))

	// Other views are created on demand (lazy loading).
	app.createView(command.ViewDashboard)
	app.createView(command.ViewStatus)
	app.createView(app.currentView)

	// Computes the available height and propagates it to the views.
	app.resize(width, height)

	return app
}

// defaultView resolves the configured landing view, falling back to the
// dashboard when the setting is missing or unparseable.
func defaultView(cfg *config.Config) command.ViewType {
	if cfg.App.DefaultView == "" {
		return command.ViewDashboard
	}
	parsed, err := command.Parse(cfg.App.DefaultView)
	if err != nil || parsed == "" {
		return command.ViewDashboard
	}
	return parsed
}

// AttachProgram gives the router the handle an MCP request needs to reach
// Update().
//
// It is called by main() between tea.NewProgram and p.Run(), which is the only
// window where writing a field of the model is safe outside Update: the loop
// has not started, so there is nothing to race with. Anything that needs the
// program later reads it; nothing writes it again.
func (a *App) AttachProgram(p *tea.Program) {
	a.program = p
	a.mcpDispatch = mcpDispatcher{program: p}
}

// Init initializes the application
func (a *App) Init() tea.Cmd {
	// Note: resize() is already called in newWithSize() to initialize the dimensions
	cmds := []tea.Cmd{a.tryAutoLogin(), a.startMCPCmd(), a.restoreForwardsCmd(), a.detectScanTools()}

	if view, ok := a.views[a.currentView]; ok {
		cmds = append(cmds, view.Init())
	}

	return tea.Batch(cmds...)
}

// requestResize asks for a fresh layout at the current size. Every handler that
// changes what the window holds returns one, because the viewport height is
// budgeted against the header and the active view's footer.
func (a *App) requestResize() tea.Cmd {
	return func() tea.Msg {
		return tea.WindowSizeMsg{Width: a.width, Height: a.height}
	}
}

// resize lays out the window. It **iterates**, and that is necessary: the
// footer height is asked of the view (Rule 124), but a view whose footer
// depends on its own size — the dashboard hides its tab line once only one
	a.anim.blinkOn = true
	return a.sendFrameTo(a.currentView)
}

func (a *App) update(msg tea.Msg) (tea.Model, tea.Cmd) {
	switch msg := msg.(type) {
	case tea.WindowSizeMsg:
		a.resize(msg.Width, msg.Height)
		return a, nil

	case tea.ColorProfileMsg:
		// Router state only (View sets the terminal background); not forwarded.
		a.colorProfile = msg.Profile
		return a, nil

	case tea.BlurMsg:
		return a.handleTerminalBlur()

	case tea.FocusMsg:
		return a.handleTerminalFocus()

	case tea.KeyPressMsg:
		_, focusCmd := a.handleTerminalFocus() // input proves the terminal has the focus
		model, keyCmd := a.handleKeyMsg(msg)
		return model, tea.Batch(focusCmd, keyCmd)

	case tea.PasteMsg:
		_, focusCmd := a.handleTerminalFocus() // input proves the terminal has the focus
		model, pasteCmd := a.handlePasteMsg(msg)
		return model, tea.Batch(focusCmd, pasteCmd)

