//
// "auto" with a known answer applies at once without asking again. "auto"
// without one starts from the dark theme; at startup the query is armed by
// themeInitCmd. A named theme cancels any wait.
func (a *App) chooseTheme(app config.AppConfig, startup bool) string {
	var r theme.Resolution
	if app.IsAutoTheme() {
		wait := startup || a.theme.pending
		if !wait {
			a.theme.gen++
		}
		bg := a.theme.answer
		r = theme.ResolveAuto(bg, app.EffectiveThemeDark(), app.EffectiveThemeLight())
		a.theme.pending = wait && bg == theme.BackgroundUnknown
	} else {
		a.theme.gen++
		a.theme.pending = false
